#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define MAXM 600005

int head[MAXN], to[MAXM], nxt[MAXM];
int edge_cnt = 0;

void add_edge(int u, int v) {
    edge_cnt++;
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt;
}

int team[MAXN];
int queue[MAXN];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) {
        int m;
        if (scanf("%d", &m) != 1) break;
        for (int j = 0; j < m; j++) {
            int x;
            scanf("%d", &x);
            add_edge(i, x);
        }
    }

    int q_start = 0, q_end = 0;

    team[1] = 1;
    queue[q_end++] = 1;

    while (q_start < q_end) {
        int u = queue[q_start++];
        int t = team[u];
        int next_team = (t == 1) ? 2 : 1;

        for (int e = head[u]; e != 0; e = nxt[e]) {
            int v = to[e];
            if (team[v] == 0) {
                team[v] = next_team;
                queue[q_end++] = v;
            }
        }
    }

    // Imprimir o primeiro time
    int first = 1;
    for (int i = 1; i <= n; i++) {
        if (team[i] == 1) {
            if (!first) {
                putchar(' ');
            }
            printf("%d", i);
            first = 0;
        }
    }
    putchar('\n');

    // Imprimir o segundo time
    first = 1;
    for (int i = 1; i <= n; i++) {
        if (team[i] == 2) {
            if (!first) {
                putchar(' ');
            }
            printf("%d", i);
            first = 0;
        }
    }
    putchar('\n');

    return 0;
}
